// The styles added to the shared library on top of the course guide's 24: the new looks of «حولني الى الستايل الكرتوني»
// and the rest of the map, so the library reaches 100 base styles in 14 families, each under the studio or school
// whose signature it carries.
//
// The research behind each one (making-of interviews and trade press, gathered October 2026):
//   - Spider-Verse: animated on twos, smears instead of motion blur, halftone lighting and hatched shadows, ink lines
//     placed in 3D (slashfilm.com/562748, motionpictures.org, sessions.edu);
//   - Arcane / Fortiche: 3D bodies with hand-painted textures, smoke and fire drawn as 2D effects (vfxvoice.com);
//   - The Wild Robot: every surface hand-painted, impressionistic soft edges, colour authored in a painter's gamut
//     (beforesandafters.com/2025/01/10, postmagazine.com);
//   - Puss in Boots: The Last Wish: "a fairy tale painting", Puss on twos and the wolf on ones, 2D splash effects (awn.com);
//   - Klaus: hand-drawn animation lit with volumetric light by a tool that tracks the drawn lines (80.lv, beforesandafters.com);
//   - Wolfwalkers: the town as a 17th-century woodcut (colour stripped, black and red kept, chunky line), the forest in
//     pencil, charcoal and watercolour (blog.frame.io/2021/05/03);
//   - Laika moves the puppet on every frame with 3D-printed replacement faces ("forget they are puppets"), Aardman keeps
//     the fingerprints in the plasticine (boxofficepro.com, filmstories.co.uk);
//   - limited animation and rubber hose: UPA's flat modernism, Hanna-Barbera's held cels over painted backgrounds,
//     Fleischer's curved boneless limbs (en.wikipedia.org/wiki/Limited_animation, /Rubber_hose_animation);
//   - Persian miniature: luminous flatness, no cast shadows, even light, simultaneous spaces, gold and lapis
//     (en.wikipedia.org/wiki/Persian_miniature);
//   - game looks: low-poly, cel-shaded, pixel, voxel, hand-painted textures, stylised hero 3D (pixune.com/blog/game-art-styles).
// As in the 24, the prompt texts name only what a generator can reproduce — line, shading, texture, palette, light,
// material, timing — never an artist, a studio or a work; the studio is the school the style is filed under, shown
// to the person in Arabic.

export interface StyleFamily {
  id: string;
  name: string;
  icon: string;
  hint: string;
  /** the scene the family's sample pictures show, so the styles of one family compare on the same thing */
  scene: string;
  /** the tile's colours while a style has no picture yet */
  tone: [string, string];
}

